  Record ap1H (regs : bvmap 5 word) (mem : word -> option byte) (sp : word) (can : Z) : Prop := AP1H {
    Q1  : getr regs 1 = Z_to_bv 64 0x0bec68;
    Q2  : getr regs 2 = sp;
